public class METNat3040RegisterUpdateUIBuilder  extends SysOperationAutomaticUIBuilder
{
    METNat3040RegisterUpdateContract    contract;
    DialogField                         dialogUpdateNat3040;
    DialogField                         dialogNat3040Number;

    

}

Method.Source:
    public void postBuild()
    {
        FormBuildGroupControl formBuildGroupControl = dialog.curFormGroup();
        formBuildGroupControl.columns(2);
        contract = this.dataContractObject();
        //dialog.addGroup("@SYS920");
        //this.addDialogField(methodStr(METNat3040RegisterUpdateContract, parmUpdateNat3040),contract);
        //this.addDialogField(methodStr(METNat3040RegisterUpdateContract, parmNat3040Number),contract);
        dialog.allowUpdateOnSelectCtrl(true);


    }

    /// <summary>
    ///
    /// </summary>
    public void dialogSelectCtrl()
    {
        //super();

        // get references to dialog controls after creation
        dialogUpdateNat3040 = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METNat3040RegisterUpdateContract, parmUpdateNat3040));

        dialogNat3040Number = this.bindInfo().getDialogField(this.dataContractObject(),
                                    methodStr(METNat3040RegisterUpdateContract, parmNat3040Number));

        if(dialogUpdateNat3040.value() == NoYes::Yes)
        {
            dialogNat3040Number.allowEdit(false);
        }
    }
